      {|INSERT INTO "documents"
          (source_kind, source_name, locator, revision, content_hash, contents)
        VALUES (?, ?, ?, 0, ?, ?)
        ON CONFLICT (source_kind, source_name, locator) DO UPDATE
          SET revision =
                CASE
                  WHEN content_hash IS NOT excluded.content_hash
                  THEN revision + 1
                  ELSE revision
                END,
              content_hash = excluded.content_hash,
              contents = excluded.contents
        RETURNING doc_id|}
      (source_params source locator
      @ [
          U.Nullable_text
            (Option.map Util.Text.validate_exn
               (content_hash_of_contents contents));
          param_of_contents contents;
        ])
      ~f:(fun stmt -> A.Doc_id.of_int64_exn (Sqlite3.column_int64 stmt 0))

  let row_to_doc_meta stmt : T.doc_meta =
    {
      doc_id = A.Doc_id.of_int64_exn (Sqlite3.column_int64 stmt col_doc_id);
      source_doc =
        {
          source =
            source_of_columns
              ( Sqlite3.column_text stmt col_source_kind,
                Sqlite3.column_text stmt col_source_name );
          locator = Sqlite3.column_text stmt col_locator;
        };
      revision = Int64.to_int (Sqlite3.column_int64 stmt col_revision);
      content_hash =
        Sqlite3.column stmt col_content_hash |> Sqlite3.Data.to_string;
    }

  let get_by_id db (doc_id : T.doc_id) : T.doc_meta option =
    U.query_rows db
      {|SELECT doc_id, source_kind, source_name, locator, revision, content_hash
        FROM "documents" WHERE doc_id = ?|}
      [ U.Int64 (A.Doc_id.to_int64 doc_id) ]
      ~f:row_to_doc_meta
    |> function
    | [] -> None
    | x :: _ -> Some x

  let get_by_locator db ~(source : T.source) locator : T.doc_meta option =
    U.query_rows db
      {|SELECT doc_id, source_kind, source_name, locator, revision, content_hash
        FROM "documents"
        WHERE source_kind = ? AND source_name = ? AND locator = ?|}
      (source_params source locator)
      ~f:row_to_doc_meta
    |> function
    | [] -> None
    | x :: _ -> Some x
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_id = ? AND "start" < ? AND "end" > ?|}
         select_cols)
      [
        U.Int64 (A.Doc_id.to_int64 doc_id);
        U.Int64 (Int64.of_int end_);
        U.Int64 (Int64.of_int start);
      ]
      ~f:row_to_anchor

  let get_stale db (doc_id : T.doc_id) ~doc_revision :
      Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_id = ? AND doc_revision_attempt < ?|}
         select_cols)
      [
        U.Int64 (A.Doc_id.to_int64 doc_id);
        U.Int64 (Int64.of_int doc_revision);
      ]
      ~f:row_to_anchor

  let get_all db : Internal_types.anchor list =
    U.query_rows db
      (sprintf {|SELECT %s FROM "anchors"|} select_cols)
      [] ~f:row_to_anchor

  let get_all_current db : Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_revision = doc_revision_attempt|}
         select_cols)
      [] ~f:row_to_anchor

  let get_all_stale db : Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_revision < doc_revision_attempt|}
         select_cols)
      [] ~f:row_to_anchor
end
    U.exec_params db {|DELETE FROM "containers" WHERE doc_id = ?|}
      [ U.Int64 (A.Doc_id.to_int64 doc_id) ]
end

module Shingles = struct
  let create_table db =
    U.exec db
      {|
        CREATE TABLE IF NOT EXISTS "shingles" (
          shingle BLOB    NOT NULL,
          doc_id  INTEGER NOT NULL REFERENCES documents(doc_id),
          "start" INTEGER NOT NULL,
          "end"   INTEGER NOT NULL,
          PRIMARY KEY (doc_id, "start")
        )
      |};
    U.exec db
      {|CREATE INDEX IF NOT EXISTS "shingles_shingle" ON "shingles" (shingle)|}

  (* [find]'s own column order below: it omits [shingle] (already known to
     the caller -- that's what it searched by) and so doesn't match this
     table's own column positions above. *)
  let col_find_doc_id = 0
  let col_find_start = 1
  let col_find_end = 2

  let add db ~(doc_id : T.doc_id) ~(shingle : Internal_types.shingle_str)
      ~(range : T.range) =
    U.exec_params db
      {|INSERT OR REPLACE INTO "shingles" (shingle, doc_id, "start", "end")
        VALUES (?, ?, ?, ?)|}
      [
        U.Blob (shingle :> string);
        U.Int64 (A.Doc_id.to_int64 doc_id);
        U.Int64 (Int64.of_int range.start);
        U.Int64 (Int64.of_int range.end_);
      ]

  let find db (shingle : Internal_types.shingle_str) :
      (T.doc_id * T.range) list =
    U.query_rows db
      {|SELECT doc_id, "start", "end" FROM "shingles" WHERE shingle = ?|}
      [ U.Blob (shingle :> string) ]
      ~f:(fun stmt ->
        ( A.Doc_id.of_int64_exn (Sqlite3.column_int64 stmt col_find_doc_id),
          ({
             start = Int64.to_int (Sqlite3.column_int64 stmt col_find_start);
             end_ = Int64.to_int (Sqlite3.column_int64 stmt col_find_end);
           }
            : T.range) ))

  let delete_doc db (doc_id : T.doc_id) =
    U.exec_params db {|DELETE FROM "shingles" WHERE doc_id = ?|}
      [ U.Int64 (A.Doc_id.to_int64 doc_id) ]
end

